import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 32 Shopping made easy","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 32 Shopping made easy","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 31 Success story","link":"/life/english/new-concept/book-2/unit-02/lesson-031"},"next":{"text":"第二册：实践与进步 · Lesson 33 Out of the darkness","link":"/life/english/new-concept/book-2/unit-02/lesson-033"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 31 Success story","link":"/life/english/new-concept/book-2/unit-02/lesson-031"},"next":{"text":"第二册：实践与进步 · Lesson 33 Out of the darkness","link":"/life/english/new-concept/book-2/unit-02/lesson-033"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-032.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-032.md"}'),s={name:"life/english/new-concept/book-2/unit-02/lesson-032.md"};function i(r,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-32-shopping-made-easy" tabindex="-1">第二册：实践与进步 · Lesson 32 Shopping made easy <a class="header-anchor" href="#第二册-实践与进步-·-lesson-32-shopping-made-easy" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 32 Shopping made easy&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>购物环境的便利也要求明确流程和责任；练习已经发生的失窃与已完成的调查结果。本课的语言观察是：has been found 说明东西已经找回，与现在有关；was found yesterday 用于明确昨天的事件。被动不代表执行者必定未知，只是可以不写。完成学习后，请描述一次退货流程，包含找到凭证、核查和结果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>shop</td><td>/ʃɒp/</td><td>n.</td><td>商店</td><td>a corner shop</td></tr><tr><td>assistant</td><td>/əˈsɪstənt/</td><td>n.</td><td>助手；店员</td><td>a shop assistant</td></tr><tr><td>receipt</td><td>/rɪˈsiːt/</td><td>n.</td><td>收据</td><td>keep a receipt</td></tr><tr><td>steal</td><td>/stiːl/</td><td>v.</td><td>偷窃</td><td>steal a bicycle</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>pay for — 为商品付款</li><li>take something back — 把某物退回，代词用 take it back</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：has been found 说明东西已经找回，与现在有关；was found yesterday 用于明确昨天的事件。被动不代表执行者必定未知，只是可以不写。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The missing receipt has been found behind the counter.</p></blockquote><p>丢失的收据已经在柜台后面找到了。</p><p>receipt 是单数承受者，has been found 为完成时被动；behind the counter 说明发现地点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>has found the receipt 是主动；receipt has found 缺少合理宾语且让收据成为发现者。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 found behind 的辅音连接；将 has been found 连作一个谓语，不漏 been。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The missing receipt has been found behind the counter. The assistant checked the date. The customer then received a refund.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述一次退货流程，包含找到凭证、核查和结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：receipt 是单数承受者，has been found 为完成时被动；behind the counter 说明发现地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has found the receipt 是主动；receipt has found 缺少合理宾语且让收据成为发现者。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全：The receipt has ___ found.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 完成时被动为 has/have been done。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>退款前店员核对了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The date.</p><p><strong>解析：</strong> checked the date 明确核对项，没有说商品价格。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 Someone has found the receipt 改为被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The receipt has been found.</p><p><strong>解析：</strong> 不重要的执行者 someone 可省略。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-031">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-033">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
